def get_args():
    from torch._dynamo.testing import rand_strided
    arg0_1 = rand_strided((2, 64, 4, 64), (16384, 256, 64, 1), device='cuda:0', dtype=torch.float32)
    arg1_1 = rand_strided((2, 64, 2, 64), (8192, 128, 64, 1), device='cuda:0', dtype=torch.float32)
    arg2_1 = rand_strided((2, 64, 2, 64), (8192, 128, 64, 1), device='cuda:0', dtype=torch.float32)
    arg3_1 = rand_strided((2, 64, 4, 64), (16384, 256, 64, 1), device='cuda:0', dtype=torch.float32)
    arg4_1 = rand_strided((2, 64, 4), (256, 4, 1), device='cuda:0', dtype=torch.float32)
    return [arg0_1, arg1_1, arg2_1, arg3_1, arg4_1]


def benchmark_compiled_module(args, times=10, repeat=10):
    from torch._inductor.utils import print_performance
    fn = lambda: call(list(args))
    return print_performance(fn, times=times, repeat=repeat, device='cuda')


if __name__ == "__main__":
    from torch._inductor.wrapper_benchmark import compiled_module_main
    args = get_args()
    compiled_module_main('None', lambda times, repeat: benchmark_compiled_module(args, times=times, repeat=repeat))


